import React from 'react';
import './report.css';
import {Ban,BarChart3,Boxes,ClipboardList,House,MoreVertical,PanelLeftClose,PanelLeftOpen,Settings,Tags,Users} from 'lucide-react';
import{useEffect,useState}from'react';import{Routes,Route,Link,NavLink,Navigate,useNavigate,useParams,useLocation}from'react-router-dom';import{motion}from'framer-motion';import{ShoppingBag,Search,User,ArrowRight,ArrowLeft,Minus,Plus,Trash2,Package,LayoutDashboard,Store as StoreIcon,LogOut,Menu,X,ShieldCheck,Truck,Heart,Star,Eye,EyeOff}from'lucide-react';import{useAuth}from'./context/AuthContext';import{useCart}from'./context/CartContext';import api from'./services/api';import{toast}from'sonner';import{ResponsiveContainer,AreaChart,Area,XAxis,YAxis,Tooltip}from'recharts';
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n||0);const img=(p)=>p.images?.[0]||'https://placehold.co/800x800/eaf7fd/278cc2?text=CLARAYO';
function Header(){const{user,logout}=useAuth(),{count}=useCart();const[open,setOpen]=useState(false),profilePath=user?.role==='admin'?'/admin/profile':user?.role==='seller'?'/seller/profile':'/profile';return <header><Link className="brand" to="/"><span>●</span> CLARAYO</Link><nav className={open?'open':''}><NavLink to="/">Home</NavLink><NavLink to="/about">About</NavLink><NavLink to="/products">Products</NavLink>{!user&&<NavLink to="/services">Services</NavLink>}{user?.role==='customer'&&<><NavLink to="/my-orders">My Orders</NavLink><NavLink to="/wishlist">Wishlist</NavLink></>}{user?.role==='seller'&&<><NavLink to="/seller">Seller Hub</NavLink><NavLink to="/my-orders">My Purchases</NavLink></>}{user?.role==='admin'&&<NavLink to="/admin">Admin</NavLink>}{user?<><NavLink to={profilePath}><User size={18}/> {user.name.split(' ')[0]}</NavLink><button className="link" title="Log out" onClick={logout}><LogOut size={18}/></button></>:<NavLink to="/login">Sign in</NavLink>}<NavLink className="cartlink" to="/cart"><ShoppingBag className="cart-bag" key={`cart-${count}`}/><b key={`cart-count-${count}`}>{count}</b></NavLink></nav><button className="mobile" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></header>}
function Layout({children}){return <><Header/><main>{children}</main><footer><div className="brand"><span>●</span> CLARAYO</div><p>A thoughtful marketplace for everyday discoveries.</p><small>© 2026 CLARAYO. Built for better shopping.</small></footer></>}
function WishlistButton({id,onRemove}){const{user}=useAuth(),nav=useNavigate();const toggle=async e=>{e.preventDefault();e.stopPropagation();if(!user)return nav('/login');try{if(onRemove){await api.delete(`/customers/wishlist/${id}`);onRemove(id);toast.success('Removed from wishlist')}else{await api.post(`/customers/wishlist/${id}`);toast.success('Saved to wishlist')}}catch(e){toast.error(e.message)}};if(user&&user.role!=='customer')return null;return <button className="wish-btn" title="Save to wishlist" onClick={toggle}><Heart size={18}/></button>}
function ProductCard({p,onRemove}){return <motion.article className="product-card" whileHover={{y:-5}}><Link to={`/products/${p._id}`}><div className="product-img"><img src={img(p)} onError={e=>e.currentTarget.src='https://placehold.co/800x800/eaf7fd/278cc2?text=CLARAYO'}/>{p.featured&&<span className="badge">Featured</span>}<WishlistButton id={p._id} onRemove={onRemove}/></div><div className="product-copy"><small>{p.category?.name||'Collection'} · {p.store?.storeName}</small><h3>{p.name}</h3><div className="stars"><Star size={14} fill="currentColor"/> {p.rating||'New'}</div><strong>{money(p.price)}</strong><span className={p.stock?'stock':'out'}>{p.stock?`${p.stock} available`:'Out of stock'}</span></div></Link></motion.article>}
function Wishlist(){const[items,setItems]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{api.get('/customers/wishlist').then(r=>setItems(r.data.data)).catch(e=>toast.error(e.message)).finally(()=>setLoading(false))},[]);return <Layout><section className="narrow"><div className="page-head"><span className="eyebrow">SAVED FOR LATER</span><h1>Your wishlist</h1><p>Keep track of products you may want to purchase.</p></div>{loading?<div className="loading">Loading wishlist…</div>:items.length?<div className="grid">{items.map(p=><ProductCard key={p._id} p={p} onRemove={id=>setItems(items.filter(x=>x._id!==id))}/>)}</div>:<Empty title="Your wishlist is empty" text="Save products you love while browsing." action="Browse products"/>}</section></Layout>}
function CustomerHome(){const[products,setProducts]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{api.get('/products',{params:{featured:true,limit:12}}).then(r=>setProducts(r.data.data)).catch(e=>toast.error(e.message)).finally(()=>setLoading(false))},[]);return <Layout><section className="customer-welcome"><span className="eyebrow">FEATURED FROM OUR SELLERS</span><h1>Products selected for you</h1><p>Discover featured items offered by approved CLARAYO sellers.</p></section><section className="catalog customer-featured">{loading?<div className="skeleton-grid">{[1,2,3,4].map(x=><i key={x}/>)}</div>:products.length?<div className="grid">{products.map(p=><ProductCard key={p._id} p={p}/>)}</div>:<Empty title="No featured products yet" text="Featured products from approved sellers will appear here."/>}</section></Layout>}
function RootPage(){const{user}=useAuth();if(user?.role==='admin')return <Navigate to="/admin" replace/>;return user?.role==='customer'?<CustomerHome/>:<Home/>}
function Home(){const[p,setP]=useState([]),[cats,setCats]=useState([]);useEffect(()=>{Promise.all([api.get('/products?limit=8'),api.get('/categories')]).then(([a,b])=>{setP(a.data.data);setCats(b.data.data)}).catch(()=>{})},[]);return <Layout><section className="hero"><motion.div initial={{opacity:0,y:24}} animate={{opacity:1,y:0}}><span className="eyebrow">WELCOME TO CLARAYO</span><h1>Your complete<br/><em>online marketplace.</em></h1><p>CLARAYO connects customers with trusted independent sellers. Discover products, manage a store, and track every order through one secure and easy-to-use system.</p><Link className="btn" to="/products">Browse products <ArrowRight size={18}/></Link><div className="trust"><span><ShieldCheck/> Secure accounts</span><span><Truck/> Order tracking</span></div></motion.div><div className="hero-image"><img src="https://images.unsplash.com/photo-1607082349566-187342175e2f?w=1200"/><div className="float-card"><small>ONE CONNECTED SYSTEM</small><b>Shop · Sell · Manage</b></div></div></section><section className="system-intro section"><div className="section-head"><div><span className="eyebrow">WHAT YOU CAN DO</span><h2>Everything you need in one marketplace</h2></div><Link to="/services">Explore services <ArrowRight size={16}/></Link></div><div className="feature-grid"><article><ShoppingBag/><h3>Shop with confidence</h3><p>Search products, manage your cart, place secure COD orders, and follow delivery progress.</p><Link to="/products">View products →</Link></article><article><StoreIcon/><h3>Grow as a seller</h3><p>Apply for a store, manage inventory, process orders, and understand sales performance.</p><Link to="/register">Become a seller →</Link></article><article><LayoutDashboard/><h3>Manage efficiently</h3><p>Role-based dashboards keep marketplace operations, approvals, and reports organized.</p><Link to="/services">Learn more →</Link></article></div></section><section className="section"><div className="section-head"><div><span className="eyebrow">SHOP BY CATEGORY</span><h2>Find your next favorite</h2></div><Link to="/products">View all <ArrowRight size={16}/></Link></div>{cats.length?<div className="category-row">{cats.map((c,i)=><Link key={c._id} to={`/categories/${c.slug}`}><div className={`cat c${i%4}`}>{['✦','⌂','◌','♡'][i%4]}</div><b>{c.name}</b></Link>)}</div>:<p className="section-empty">Categories will appear here when the administrator adds them.</p>}</section><section className="section alt"><div className="section-head"><div><span className="eyebrow">LATEST PRODUCTS</span><h2>Discover what’s new</h2></div></div>{p.length?<div className="grid">{p.map(x=><ProductCard p={x} key={x._id}/>)}</div>:<Empty title="The marketplace is opening soon" text="Products from approved sellers will appear here."/>}</section><section className="manifesto"><span>Shop small. Dream big.</span><h2>Every order supports an independent seller.</h2><Link className="btn light" to="/products">Explore the marketplace</Link></section></Layout>}
function Products(){const[p,setP]=useState([]),[cats,setCats]=useState([]),[query,setQuery]=useState(''),[cat,setCat]=useState(''),[sort,setSort]=useState('newest'),[loading,setLoading]=useState(true);useEffect(()=>{api.get('/categories').then(r=>setCats(r.data.data))},[]);useEffect(()=>{setLoading(true);api.get('/products',{params:{search:query,category:cat,sort}}).then(r=>setP(r.data.data)).finally(()=>setLoading(false))},[query,cat,sort]);return <Layout><section className="page-title"><span className="eyebrow">THE MARKETPLACE</span><h1>Discover something good</h1><p>Independent sellers. Thoughtful products. Endless possibilities.</p></section><section className="catalog"><div className="toolbar"><label className="search"><Search size={19}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search products..."/></label><select value={cat} onChange={e=>setCat(e.target.value)}><option value="">All categories</option>{cats.map(c=><option key={c._id} value={c._id}>{c.name}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest</option><option value="price_asc">Price: low to high</option><option value="price_desc">Price: high to low</option><option value="popular">Most popular</option></select></div>{loading?<div className="skeleton-grid">{[1,2,3,4].map(x=><i key={x}/>)}</div>:p.length?<div className="grid">{p.map(x=><ProductCard p={x} key={x._id}/>)}</div>:<Empty title="No products found" text="Try a different search or category."/>}</section></Layout>}
function Detail(){const{id}=useParams(),[p,setP]=useState(null),[q,setQ]=useState(1),[added,setAdded]=useState(false),[selectedSize,setSelectedSize]=useState(''),{add}=useCart(),{user}=useAuth();useEffect(()=>{api.get(`/products/${id}`).then(r=>setP(r.data.data)).catch(e=>toast.error(e.message))},[id]);if(!p)return <Layout><div className="loading">Loading product…</div></Layout>;const handleAdd=()=>{if(p.sizes?.length&&!selectedSize)return toast.error('Please choose a size');if(add({...p,selectedSize},q)){setAdded(true);setTimeout(()=>setAdded(false),1200)}};const sellerId=typeof p.seller==='object'?p.seller?._id:p.seller,ownProduct=user?.role==='seller'&&String(sellerId)===String(user._id);return <Layout><section className="detail"><div className="detail-img"><img src={img(p)}/></div><div><span className="eyebrow">{p.category?.name} · {p.store?.storeName}</span><h1>{p.name}</h1><div className="rating"><Star fill="currentColor"/> {p.rating||'New'} <span>({p.reviewCount} reviews)</span></div><div className="detail-price">{money(p.price)}</div><p>{p.description}</p>{p.sizes?.length>0&&<div className="size-picker"><b>Choose a size</b><div>{p.sizes.map(size=><button type="button" key={size} className={selectedSize===size?'selected':''} onClick={()=>setSelectedSize(size)}>{size}</button>)}</div></div>}<div className="qty"><button onClick={()=>setQ(Math.max(1,q-1))}><Minus/></button><b>{q}</b><button onClick={()=>setQ(Math.min(p.stock,q+1))}><Plus/></button></div><button className={`btn wide add-cart-button ${added?'is-added':''}`} disabled={!p.stock||ownProduct||added} onClick={handleAdd}><ShoppingBag/> {ownProduct?'This is your product':added?'Added to cart!':'Add to cart'}</button>{ownProduct&&<p className="own-product-note">Sellers cannot purchase their own listings. You can still shop from other sellers.</p>}<Link className="seller-box seller-box-link" to={`/stores/${p.store?.slug}`}><StoreIcon/><div><small>SOLD BY</small><b>{p.store?.storeName}</b><p>{p.store?.description}</p><span>View store <ArrowRight size={14}/></span></div></Link></div></section></Layout>}
function Storefront(){const{slug}=useParams(),{user}=useAuth(),nav=useNavigate(),[data,setData]=useState(null),[following,setFollowing]=useState(false),[busy,setBusy]=useState(false);useEffect(()=>{setData(null);api.get(`/sellers/public/${slug}`).then(async r=>{setData(r.data.data);if(user&&(user.role==='customer'||user.role==='seller')){try{const status=await api.get(`/customers/following/${r.data.data.store._id}`);setFollowing(status.data.data.following)}catch{setFollowing(false)}}}).catch(e=>toast.error(e.message))},[slug,user]);const toggleFollow=async()=>{if(!user)return nav('/login');if(!['customer','seller'].includes(user.role))return toast.error('Only shoppers can follow stores');setBusy(true);try{if(following)await api.delete(`/customers/following/${data.store._id}`);else await api.post(`/customers/following/${data.store._id}`);setFollowing(!following);setData(current=>({...current,stats:{...current.stats,followers:Math.max(0,current.stats.followers+(following?-1:1))}}));toast.success(following?'Store unfollowed':'Store followed')}catch(e){toast.error(e.message)}finally{setBusy(false)}};if(!data)return <Layout><div className="loading">Loading storeâ€¦</div></Layout>;const{store,products,stats}=data;return <Layout><section className="storefront-hero" style={store.banner?{backgroundImage:`linear-gradient(rgba(25,43,56,.72),rgba(25,43,56,.72)),url(${store.banner})`}:undefined}><div className="storefront-identity">{store.logo?<img src={store.logo} alt=""/>:<span><StoreIcon/></span>}<div><small>OFFICIAL STORE</small><h1>{store.storeName}</h1><p>{store.description||'Independent seller on CLARAYO.'}</p><div className="storefront-stats"><b><Star size={17} fill="currentColor"/> {stats.reviews?stats.rating.toFixed(1):'New'}</b><span>{stats.reviews} {stats.reviews===1?'review':'reviews'}</span><span>{stats.followers} {stats.followers===1?'follower':'followers'}</span><span>{stats.products} {stats.products===1?'product':'products'}</span></div></div></div><button className={`store-follow-button ${following?'is-following':''}`} onClick={toggleFollow} disabled={busy}>{following?'Following':busy?'Please waitâ€¦':'Follow store'}</button></section><section className="catalog storefront-products"><div className="section-head"><div><span className="eyebrow">STORE CATALOG</span><h2>Products from {store.storeName}</h2></div></div>{products.length?<div className="grid">{products.map(product=><ProductCard key={product._id} p={product}/>)}</div>:<Empty title="No products available" text="This store has no active products yet."/>}</section></Layout>}
function Cart(){const{items,update,remove,total,cartKey}=useCart();return <Layout><section className="narrow"><div className="page-head"><h1>Your bag <span>{items.length}</span></h1></div>{!items.length?<Empty title="Your bag is waiting" text="Fill it with something you love." action="Start shopping"/>:<div className="cart-layout"><div>{items.map(i=><div className="cart-item" key={cartKey(i)}><img src={img(i)}/><div><small>{i.store?.storeName}</small><h3>{i.name}</h3>{i.selectedSize&&<small className="selected-size">Size: <b>{i.selectedSize}</b></small>}<strong>{money(i.price)}</strong><div className="qty small"><button onClick={()=>update(cartKey(i),i.quantity-1)}><Minus/></button><b>{i.quantity}</b><button onClick={()=>update(cartKey(i),Math.min(i.stock,i.quantity+1))}><Plus/></button></div></div><button className="icon" onClick={()=>remove(cartKey(i))}><Trash2/></button></div>)}</div><aside className="summary"><h2>Order summary</h2><p><span>Subtotal</span><b>{money(total)}</b></p><p><span>Delivery</span><b>{total>=1500?'Free':money(99)}</b></p><hr/><p className="grand"><span>Total</span><b>{money(total+(total>=1500?0:99))}</b></p><Link className="btn wide" to="/checkout">Continue to checkout</Link></aside></div>}</section></Layout>}
function Empty({title,text,action}){return <div className="empty"><ShoppingBag/><h2>{title}</h2><p>{text}</p>{action&&<Link className="btn" to="/products">{action}</Link>}</div>}
function PasswordField({label,value,onChange,autoComplete,placeholder,maxLength}){const[visible,setVisible]=useState(false);return <label>{label}<span className="password-field"><input required minLength="8" maxLength={maxLength} type={visible?'text':'password'} autoComplete={autoComplete} value={value} onChange={onChange} placeholder={placeholder}/><button type="button" aria-label={visible?'Hide password':'Show password'} aria-pressed={visible} onClick={()=>setVisible(!visible)}>{visible?<EyeOff size={19}/>:<Eye size={19}/>}</button></span></label>}
function Auth({mode}){const{login,register}=useAuth(),nav=useNavigate(),[busy,setBusy]=useState(false),[form,setForm]=useState({firstName:'',lastName:'',email:'',password:'',confirmPassword:''}),isLogin=mode==='login';const submit=async e=>{e.preventDefault();const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!email.test(form.email.trim()))return toast.error('Enter a valid email address');if(!isLogin&&form.firstName.trim().length<2)return toast.error('First name must contain at least 2 characters');if(!isLogin&&form.lastName.trim().length<2)return toast.error('Last name must contain at least 2 characters');if(form.password.length<8)return toast.error('Password must contain at least 8 characters');if(!isLogin&&form.password.length>16)return toast.error('Password must contain no more than 16 characters');if(!isLogin&&!/[A-Za-z]/.test(form.password))return toast.error('Password must contain at least one letter');if(!isLogin&&!/\d/.test(form.password))return toast.error('Password must contain at least one number');if(!isLogin&&form.password!==form.confirmPassword)return toast.error('Passwords do not match');setBusy(true);try{const payload=isLogin?{email:form.email.trim(),password:form.password}:{name:`${form.firstName.trim()} ${form.lastName.trim()}`,email:form.email.trim(),password:form.password};const u=await(isLogin?login(payload):register(payload));toast.success(isLogin?'Welcome back':'Welcome to CLARAYO');nav(u.role==='admin'?'/admin':u.role==='seller'?'/seller':'/')}catch(e){toast.error(e.message)}finally{setBusy(false)}};return <Layout><section className={`auth-split ${isLogin?'login-mode':'register-mode'}`}><motion.div key={`intro-${mode}`} className="auth-split-intro" initial={{opacity:0,x:isLogin?-70:70}} animate={{opacity:1,x:0}} transition={{duration:.55,ease:[.22,1,.36,1]}}><span className="eyebrow">{isLogin?'WELCOME BACK':'JOIN CLARAYO'}</span><h1>{isLogin?'Good to see you again.':'Start shopping with us.'}</h1><p>{isLogin?'Sign in to manage your orders, saved products, and account.':'Create a customer account and discover products from trusted independent sellers.'}</p><div className="auth-switch"><span>{isLogin?'New to CLARAYO?':'Already registered?'}</span><Link to={isLogin?'/register':'/login'}>{isLogin?'Create an account':'Sign in instead'} <ArrowRight size={17}/></Link></div></motion.div><motion.form key={`form-${mode}`} className="auth-split-form" onSubmit={submit} noValidate initial={{opacity:0,x:isLogin?70:-70}} animate={{opacity:1,x:0}} transition={{duration:.55,ease:[.22,1,.36,1]}}><div><span className="eyebrow">{isLogin?'ACCOUNT LOGIN':'CREATE ACCOUNT'}</span><h2>{isLogin?'Sign in':'Register'}</h2><p>{isLogin?'Enter your account details below.':'It only takes a moment to get started.'}</p></div>{!isLogin&&<div className="auth-name-grid"><label>First name<input required autoComplete="given-name" value={form.firstName} onChange={e=>setForm({...form,firstName:e.target.value})} placeholder="First name"/></label><label>Last name<input required autoComplete="family-name" value={form.lastName} onChange={e=>setForm({...form,lastName:e.target.value})} placeholder="Last name"/></label></div>}<label>Email address<input required type="email" autoComplete="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="name@example.com"/></label><PasswordField label="Password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} autoComplete={isLogin?'current-password':'new-password'} placeholder={isLogin?'At least 8 characters':'8 to 16 characters'} maxLength={isLogin?undefined:16}/>{!isLogin&&<><PasswordField label="Confirm password" value={form.confirmPassword} onChange={e=>setForm({...form,confirmPassword:e.target.value})} autoComplete="new-password" placeholder="Enter password again" maxLength={16}/><small className="password-hint">Use 8 to 16 characters with at least one letter and one number.</small></>}<button disabled={busy} className="btn wide">{busy?'Please wait…':isLogin?'Sign in':'Create account'}</button><p className="auth-mobile-switch">{isLogin?<>New here? <Link to="/register">Create an account</Link></>:<>Already have an account? <Link to="/login">Sign in</Link></>}</p></motion.form></section></Layout>}
function Guard({roles,children}){const{user,loading}=useAuth(),loc=useLocation();if(loading)return <div className="loading">Checking your account…</div>;if(!user)return <Navigate to="/login" state={{from:loc}} replace/>;return roles&&!roles.includes(user.role)?<Navigate to="/" replace/>:children}
function Checkout(){const{items,total,clear}=useCart(),{user}=useAuth(),nav=useNavigate(),[busy,setBusy]=useState(false),[form,setForm]=useState({name:user?.name||'',phone:user?.phone||'',line1:user?.address?.line1||'',city:user?.address?.city||'',province:user?.address?.province||'',postalCode:user?.address?.postalCode||''});const submit=async e=>{e.preventDefault();setBusy(true);try{const r=await api.post('/orders',{items:items.map(i=>({product:i._id,quantity:i.quantity,selectedSize:i.selectedSize||''})),shippingAddress:form},{headers:{'Idempotency-Key':crypto.randomUUID()}});clear();nav(`/order-success/${r.data.data._id}`,{state:{order:r.data.data}})}catch(e){toast.error(e.message)}finally{setBusy(false)}};if(!items.length)return <Navigate to="/cart"/>;return <Layout><section className="checkout"><form onSubmit={submit}><span className="eyebrow">SECURE CHECKOUT</span><h1>Where should we send it?</h1><div className="form-grid">{[['name','Recipient name'],['phone','Phone number'],['line1','Street address'],['city','City'],['province','Province'],['postalCode','Postal code']].map(([k,l])=><label key={k}>{l}<input required value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}</div><div className="cod"><b>Cash on Delivery</b><span>Pay when your order arrives</span></div><button className="btn wide" disabled={busy}>{busy?'Placing order…':`Place order · ${money(total+(total>=1500?0:99))}`}</button></form><aside className="summary"><h2>Your order</h2>{items.map(i=><p key={`${i._id}:${i.selectedSize||''}`}><span>{i.name}{i.selectedSize?` (${i.selectedSize})`:''} × {i.quantity}</span><b>{money(i.price*i.quantity)}</b></p>)}<hr/><p className="grand"><span>Total</span><b>{money(total+(total>=1500?0:99))}</b></p></aside></section></Layout>}
function OrderSuccess(){const{id}=useParams();return <Layout><div className="success"><div>✓</div><span className="eyebrow">ORDER CONFIRMED</span><h1>It’s on its way to being yours.</h1><p>Thanks for shopping with us. Your order reference is <b>{id.slice(-8).toUpperCase()}</b>.</p><Link className="btn" to="/my-orders">Track your order</Link></div></Layout>}
function AccountTabs(){return <div className="account-tabs"><NavLink end to="/profile"><User size={18}/> Profile</NavLink><NavLink to="/settings"><Settings size={18}/> Settings</NavLink></div>}
function Profile(){const{user,setUser}=useAuth(),[form,setForm]=useState({name:user.name,phone:user.phone||'',address:user.address||{line1:'',city:'',province:'',postalCode:''}});const save=async e=>{e.preventDefault();try{const r=await api.put('/auth/me',form);setUser(r.data.data);toast.success('Profile updated')}catch(e){toast.error(e.message)}};return <Layout><section className="narrow"><div className="page-head"><h1>Hello, {user.name.split(' ')[0]}</h1><p>Manage your personal details and delivery address.</p></div><AccountTabs/><div className="account-layout"><form className="store-form" onSubmit={save}><h2>Profile details</h2><label>Full name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Phone number<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Street address<input value={form.address.line1||''} onChange={e=>setForm({...form,address:{...form.address,line1:e.target.value}})}/></label><div className="form-grid"><label>City<input value={form.address.city||''} onChange={e=>setForm({...form,address:{...form.address,city:e.target.value}})}/></label><label>Province<input value={form.address.province||''} onChange={e=>setForm({...form,address:{...form.address,province:e.target.value}})}/></label><label>Postal code<input value={form.address.postalCode||''} onChange={e=>setForm({...form,address:{...form.address,postalCode:e.target.value}})}/></label></div><button className="btn">Save profile</button></form><div><div className="profile-quick"><Link to="/my-orders"><Package/> My orders</Link><Link to="/wishlist"><Heart/> Wishlist</Link><Link to="/settings"><Settings/> Account settings</Link></div>{user.role==='customer'&&<SellerApply/>}</div></div></section></Layout>}
function CustomerSettings(){const{user}=useAuth(),[passwords,setPasswords]=useState({currentPassword:'',newPassword:''}),[busy,setBusy]=useState(false);const save=async e=>{e.preventDefault();if(passwords.newPassword.length<8||passwords.newPassword.length>16)return toast.error('New password must be 8 to 16 characters');setBusy(true);try{await api.patch('/customers/password',passwords);setPasswords({currentPassword:'',newPassword:''});toast.success('Password updated')}catch(e){toast.error(e.message)}finally{setBusy(false)}};return <Layout><section className="narrow"><div className="page-head"><h1>Account settings</h1><p>Manage the security settings for {user.email}.</p></div><AccountTabs/><form className="store-form settings-form" onSubmit={save}><h2>Change password</h2><p>Use a strong password with 8 to 16 characters.</p><label>Current password<input required type="password" autoComplete="current-password" value={passwords.currentPassword} onChange={e=>setPasswords({...passwords,currentPassword:e.target.value})}/></label><label>New password<input required minLength="8" maxLength="16" type="password" autoComplete="new-password" value={passwords.newPassword} onChange={e=>setPasswords({...passwords,newPassword:e.target.value})}/></label><button className="btn" disabled={busy}>{busy?'Updating…':'Update password'}</button></form></section></Layout>}
function SellerApply(){const[done,setDone]=useState(false),[name,setName]=useState('');const go=async()=>{try{await api.post('/sellers/apply',{storeName:name,description:'Independent CLARAYO seller'});setDone(true);toast.success('Application submitted')}catch(e){toast.error(e.message)}};return <div className="profile-card"><StoreIcon/><h3>Become a seller</h3>{done?<p>Your application is pending review.</p>:<><input placeholder="Store name" value={name} onChange={e=>setName(e.target.value)}/><button className="btn smallbtn" onClick={go}>Apply</button></>}</div>}
function Orders(){const[orders,setOrders]=useState([]);useEffect(()=>{api.get('/orders/my-orders').then(r=>setOrders(r.data.data))},[]);return <Layout><section className="narrow"><div className="page-head"><h1>Your orders</h1></div>{orders.length?orders.map(o=><Link className="order-row" key={o._id} to={`/my-orders/${o._id}`}><div className="order-thumbnail"><img src={o.items?.[0]?.image||'https://placehold.co/160x160/eaf7fd/278cc2?text=CLARAYO'} alt={o.items?.[0]?.productName||'Order product'}/>{o.items?.length>1&&<span>+{o.items.length-1}</span>}</div><div className="order-summary-copy"><b>{o.orderNumber}</b><small>{o.items?.map(item=>item.productName).join(', ')}</small><small>{new Date(o.createdAt).toLocaleDateString()}</small></div><span className={`status ${o.status}`}>{o.status}</span><strong>{money(o.total)}</strong><ArrowRight/></Link>):<Empty title="No orders yet" text="Your future finds will appear here." action="Browse products"/>}</section></Layout>}
function OrderDetail(){
  const{id}=useParams(),[o,setO]=useState(null),[review,setReview]=useState({product:'',rating:5,comment:''}),[reviewedProducts,setReviewedProducts]=useState([]),[reviewBusy,setReviewBusy]=useState(false);
  const productId=item=>String(typeof item.product==='object'?item.product?._id:item.product);
  useEffect(()=>{let active=true;api.get(`/orders/${id}`).then(async r=>{if(!active)return;setO(r.data.data);try{const reviews=await api.get(`/reviews/order/${id}`);if(active)setReviewedProducts(reviews.data.data.map(item=>String(item.product)))}catch{if(active)setReviewedProducts([])}}).catch(e=>toast.error(e.message));return()=>{active=false}},[id]);
  const cancel=async()=>{if(!confirm('Cancel this order and restore its stock?'))return;try{const r=await api.patch(`/orders/${id}/cancel`);setO(r.data.data);toast.success('Order cancelled and stock restored')}catch(e){toast.error(e.message)}};
  const submitReview=async e=>{e.preventDefault();setReviewBusy(true);try{await api.post('/reviews',{...review,order:o._id});setReviewedProducts(current=>[...new Set([...current,String(review.product)])]);toast.success('Review submitted');setReview({product:'',rating:5,comment:''})}catch(e){toast.error(e.message)}finally{setReviewBusy(false)}};
  if(!o)return <Layout><div className="loading">Loading order…</div></Layout>;
  const steps=['processing','packed','shipped','delivered'],current=steps.indexOf(o.status),reviewableItems=o.items.filter(item=>!reviewedProducts.includes(productId(item)));
  return <Layout><section className="narrow"><Link className="back-link" to="/my-orders"><ArrowLeft size={18}/> Back to orders</Link><div className="page-head"><span className="eyebrow">{o.orderNumber}</span><h1>Order details</h1></div>{o.status!=='cancelled'&&<div className="tracking">{steps.map((s,i)=><div className={i<=current?'done':''} key={s}><i>{i<current?'✓':i+1}</i><span>{s}</span></div>)}</div>}{o.items.map((i,index)=><div className="cart-item" key={`${productId(i)}-${index}`}><img src={i.image}/><div><h3>{i.productName}</h3><p>{i.quantity}{i.selectedSize&&<> · Size {i.selectedSize}</>} × {money(i.unitPrice)}</p></div><b>{money(i.subtotal)}</b></div>)}<div className="summary standalone"><p><span>Status</span><b className="status">{o.status}</b></p><p className="grand"><span>Total</span><b>{money(o.total)}</b></p>{o.status==='processing'&&<button className="danger" onClick={cancel}>Cancel order</button>}</div>{o.status==='delivered'&&(reviewableItems.length?<form className="review-form" onSubmit={submitReview}><h2>Review a purchased product</h2><select required value={review.product} onChange={e=>setReview({...review,product:e.target.value})}><option value="">Select product</option>{reviewableItems.map((i,index)=><option key={`${productId(i)}-${index}`} value={productId(i)}>{i.productName}</option>)}</select><select value={review.rating} onChange={e=>setReview({...review,rating:Number(e.target.value)})}>{[5,4,3,2,1].map(x=><option key={x} value={x}>{x} stars</option>)}</select><textarea required placeholder="Share your experience" value={review.comment} onChange={e=>setReview({...review,comment:e.target.value})}/><button className="btn" disabled={reviewBusy}>{reviewBusy?'Submitting…':'Submit verified review'}</button></form>:<div className="review-complete"><span>✓</span><div><h2>Review completed</h2><p>Thank you. You have reviewed every product in this order.</p></div></div>)}</section></Layout>
}
const dashNav={seller:[['/seller','Overview'],['/seller/products','Products'],['/seller/orders','Orders'],['/seller/store','Store profile'],['/seller/followers','Followers'],['/seller/reviews','Reviews'],['/seller/reports','Reports']],admin:[['/admin','Overview'],['/admin/seller-applications','Seller applications'],['/admin/customers','Customers'],['/admin/sellers','Sellers'],['/admin/products','Products'],['/admin/orders','Orders'],['/admin/categories','Categories'],['/admin/reports','Reports']]};
function DashboardUserMenu({role}){const{user,logout}=useAuth(),[open,setOpen]=useState(false),nav=useNavigate();const signOut=()=>{logout();nav('/login')};return <div className="dashboard-user"><button aria-label="Open account menu" onClick={()=>setOpen(!open)}><User/></button>{open&&<div className="user-dropdown"><div><b>{user.name}</b><small>{user.email}</small></div>{role!=='admin'&&<Link to="/" onClick={()=>setOpen(false)}><House size={16}/> Home</Link>}<Link to={`/${role}/profile`} onClick={()=>setOpen(false)}><User size={16}/> Profile</Link><Link to={`/${role}/settings`} onClick={()=>setOpen(false)}><ShieldCheck size={16}/> Settings</Link><button onClick={signOut}><LogOut size={16}/> Logout</button></div>}</div>}
function DashboardAccount({mode}){const{user,setUser}=useAuth(),[profile,setProfile]=useState({name:user.name,phone:user.phone||''}),[passwords,setPasswords]=useState({currentPassword:'',newPassword:''});const saveProfile=async e=>{e.preventDefault();try{const r=await api.put('/auth/me',profile);setUser(r.data.data);toast.success('Profile updated')}catch(e){toast.error(e.message)}};const savePassword=async e=>{e.preventDefault();if(passwords.newPassword.length<8||passwords.newPassword.length>16)return toast.error('New password must be 8 to 16 characters');try{await api.patch('/customers/password',passwords);setPasswords({currentPassword:'',newPassword:''});toast.success('Password updated')}catch(e){toast.error(e.message)}};return mode==='profile'?<form className="dashboard-account" onSubmit={saveProfile}><h2>Profile information</h2><p>Update the information associated with your administrator account.</p><label>Full name<input required value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})}/></label><label>Email address<input disabled value={user.email}/></label><label>Phone number<input value={profile.phone} onChange={e=>setProfile({...profile,phone:e.target.value})}/></label><button className="btn">Save profile</button></form>:<form className="dashboard-account" onSubmit={savePassword}><h2>Account settings</h2><p>Use a strong password with 8 to 16 characters.</p><label>Current password<input required type="password" value={passwords.currentPassword} onChange={e=>setPasswords({...passwords,currentPassword:e.target.value})}/></label><label>New password<input required minLength="8" maxLength="16" type="password" value={passwords.newPassword} onChange={e=>setPasswords({...passwords,newPassword:e.target.value})}/></label><button className="btn">Change password</button></form>}
function DashboardNavIcon({label}){const text=label.toLowerCase();if(text.includes('overview'))return <LayoutDashboard/>;if(text.includes('product'))return <Boxes/>;if(text.includes('order'))return <ClipboardList/>;if(text.includes('store')||text.includes('seller'))return <StoreIcon/>;if(text.includes('customer')||text.includes('follower'))return <Users/>;if(text.includes('categor'))return <Tags/>;if(text.includes('report'))return <BarChart3/>;return <Settings/>}
function DashboardSidebarToggle({open,setOpen}){return <button type="button" className="dashboard-mobile-toggle grid h-11 w-11 shrink-0 place-items-center rounded-xl border border-slate-200 bg-white text-slate-700 shadow-sm transition hover:border-dashboard-500 hover:text-dashboard-600 md:hidden" aria-label={open?'Close dashboard navigation':'Open dashboard navigation'} aria-expanded={open} onClick={()=>setOpen(!open)}>{open?<PanelLeftClose size={21}/>:<PanelLeftOpen size={21}/>}</button>}
function Dashboard({role,view='overview'}){const[stats,setStats]=useState(null),[data,setData]=useState([]),[sidebarOpen,setSidebarOpen]=useState(false);const base=role==='admin'?'/admin':'/seller',accountView=view==='profile'||view==='settings';useEffect(()=>{if(accountView)return;if(view==='overview')api.get(`${base}/dashboard`).then(r=>setStats(r.data.data));else if(view==='applications')api.get('/admin/seller-applications').then(r=>setData(r.data.data));else api.get(`${base}/${view}`).then(r=>setData(r.data.data))},[role,view,accountView]);const approve=async(id,status)=>{await api.patch(`/admin/seller-applications/${id}`,{status});setData(data.filter(x=>x._id!==id));toast.success(`Seller ${status}`)};return <div className="dashboard-shell"><button type="button" className={`dashboard-overlay ${sidebarOpen?'is-visible':''}`} aria-label="Close navigation" onClick={()=>setSidebarOpen(false)}/><motion.aside initial={false} className={`modern-sidebar ${sidebarOpen?'is-open':''}`}><div className="modern-sidebar-header"><Link className="modern-sidebar-brand" to="/" title="CLARAYO"><span>S</span><b>CLARAYO</b></Link><button type="button" className="modern-sidebar-close" aria-label="Close navigation" onClick={()=>setSidebarOpen(false)}><X size={21}/></button></div><div className="modern-sidebar-label"><p>{role} workspace</p><small>{role.slice(0,1)}</small></div><nav className="modern-sidebar-nav">{dashNav[role].map(([to,l])=><NavLink end key={to} to={to} title={l} onClick={()=>setSidebarOpen(false)} className={({isActive})=>`modern-sidebar-link ${isActive?'is-active':''}`}><span><DashboardNavIcon label={l}/></span><b>{l}</b></NavLink>)}</nav></motion.aside><main className="modern-dashboard-main"><div className="modern-dashboard-top"><div className="modern-dashboard-title"><DashboardSidebarToggle open={sidebarOpen} setOpen={setSidebarOpen}/><div><span className="eyebrow">{role} dashboard</span><h1>{view==='overview'?'Welcome back':view.replace('-',' ')}</h1></div></div><DashboardUserMenu role={role}/></div>{accountView?<DashboardAccount mode={view}/>:view==='overview'?<DashboardHome role={role} stats={stats}/>:<DataView role={role} view={view} data={data} approve={approve}/>}</main></div>}
function DashboardHome({role,stats}){
  const[range,setRange]=useState(role==='seller'?'7':'30'),[metric,setMetric]=useState('revenue');
  if(!stats)return <div className="loading">Loading insights…</div>;
  const cards=role==='admin'?[['Revenue',money(stats.revenue)],['Orders',stats.orders],['Customers',stats.customers],['Products',stats.products],['Pending sellers',stats.pending]]:[['Sales',money(stats.sales)],['Orders',stats.orders],['Products',stats.products],['Low stock',stats.lowStock],['Pending orders',stats.pendingOrders||0],['Shipped orders',stats.shippedOrders||0],['Delivered orders',stats.deliveredOrders||0]];
  const adminMetricOptions={revenue:{label:'Revenue',currency:true},orders:{label:'Orders'},customers:{label:'Customers'},products:{label:'Products'},pending:{label:'Pending sellers'}},sellerMetricOptions={revenue:{label:'Revenue',currency:true},orders:{label:'Orders'},products:{label:'Products'},lowStock:{label:'Low Stock'},pendingOrders:{label:'Pending orders'},shippedOrders:{label:'Shipped orders'},deliveredOrders:{label:'Delivered orders'}};
  const metricOptions=role==='admin'?adminMetricOptions:sellerMetricOptions,activeMetric=metric,metricInfo=metricOptions[activeMetric]||metricOptions.revenue;
  const sourceActivity=stats.recent?.[activeMetric]||[];
  const dateKey=date=>{const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`};
  const activity=sourceActivity.map(entry=>({rawDate:/^\d{4}-\d{2}-\d{2}$/.test(String(entry._id||''))?String(entry._id):entry.createdAt?.slice(0,10),value:Number(entry.value??entry.total)||0,orders:Number(entry.orders)||0,units:Number(entry.units)||0})).filter(entry=>entry.rawDate);
  const byDate=new Map(activity.map(entry=>[entry.rawDate,entry]));
  const chart=range==='all'?activity.map(entry=>({...entry,name:new Date(`${entry.rawDate}T00:00:00`).toLocaleDateString('en-PH',{month:'short',day:'numeric'})})):Array.from({length:Number(range)},(_,index)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(Number(range)-1-index));const rawDate=dateKey(date),entry=byDate.get(rawDate);return{rawDate,name:date.toLocaleDateString('en-PH',{month:'short',day:'numeric'}),value:entry?.value||0,orders:entry?.orders||0,units:entry?.units||0}});
  const activeDays=chart.filter(entry=>entry.value>0).length,chartData=chart.length?chart:[{name:'No activity',value:0}],formatAxis=value=>metricInfo.currency?(value>=1000?`₱${(value/1000).toFixed(value%1000?1:0)}k`:`₱${value}`):new Intl.NumberFormat('en-PH',{notation:value>=10000?'compact':'standard'}).format(value),formatTooltip=value=>metricInfo.currency?money(value):new Intl.NumberFormat('en-PH').format(value);
  return <><div className="stat-grid">{cards.map(([label,value])=><motion.div initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} className="stat" key={label}><small>{label}</small><strong>{value}</strong><span>Live database total</span></motion.div>)}</div><div className="chart improved-chart"><div className="chart-heading"><div><h2>{role==='seller'?'Recent sales activity':`${metricInfo.label} activity`}</h2><p>{activeDays?`${activeDays} active ${activeDays===1?'day':'days'} in this period`:'No activity in this period'}</p></div><div className="chart-controls"><label className="chart-metric-select"><span>View</span><select value={metric} onChange={event=>setMetric(event.target.value)}>{Object.entries(metricOptions).map(([value,option])=><option key={value} value={value}>{option.label}</option>)}</select></label><div className="chart-filters" aria-label="Filter chart period">{[['7','7 days'],['30','30 days'],['90','90 days'],['all','All']].map(([value,label])=><button type="button" key={value} className={range===value?'active':''} onClick={()=>setRange(value)}>{label}</button>)}</div></div></div><ResponsiveContainer width="100%" height={280}><AreaChart data={chartData} margin={{top:12,right:12,left:4,bottom:0}}><defs><linearGradient id="blue" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#278CC2" stopOpacity={.34}/><stop offset="1" stopColor="#69BDE5" stopOpacity={.03}/></linearGradient></defs><XAxis dataKey="name" axisLine={false} tickLine={false} minTickGap={28}/><YAxis width={66} axisLine={false} tickLine={false} domain={[0,'auto']} allowDecimals={metricInfo.currency} tickFormatter={formatAxis}/><Tooltip formatter={value=>[formatTooltip(value),metricInfo.label]} labelFormatter={label=>`Date: ${label}`}/><Area type="monotone" dataKey="value" name={metricInfo.label} stroke="#278CC2" strokeWidth={3} fill="url(#blue)" dot={chartData.length<=14?{r:4,fill:'#fff',strokeWidth:3}:false} activeDot={{r:6}}/></AreaChart></ResponsiveContainer></div></>;
}
function SellerProducts({initial}){const[products,setProducts]=useState(initial),[categories,setCategories]=useState([]),[open,setOpen]=useState(false),[busy,setBusy]=useState(false),[form,setForm]=useState({name:'',description:'',price:'',stock:'',sku:'',category:'',image:'',featured:false,status:'active'});useEffect(()=>setProducts(initial),[initial]);useEffect(()=>{api.get('/categories').then(r=>setCategories(r.data.data))},[]);const change=e=>setForm({...form,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value});const submit=async e=>{e.preventDefault();setBusy(true);try{const payload={...form,price:Number(form.price),stock:Number(form.stock),images:form.image?[form.image]:[],sizes:form.sizes.split(',').map(size=>size.trim().toUpperCase()).filter(Boolean)};delete payload.image;const r=await api.post('/products',payload);setProducts([r.data.data,...products]);setOpen(false);setForm({name:'',description:'',price:'',stock:'',sku:'',category:'',image:'',featured:false,status:'active'});toast.success('Product added successfully')}catch(e){toast.error(e.message)}finally{setBusy(false)}};const remove=async id=>{if(!confirm('Delete this product?'))return;try{await api.delete(`/products/${id}`);setProducts(products.filter(p=>p._id!==id));toast.success('Product deleted')}catch(e){toast.error(e.message)}};return <div className="seller-products"><div className="manager-head"><div><h2>Your products</h2><p>Add and manage products belonging to your approved store.</p></div><button className="btn" onClick={()=>setOpen(!open)}>{open?<X/>:<Plus/>}{open?'Close':'Add product'}</button></div>{open&&<form className="product-form" onSubmit={submit}><label>Product name<input name="name" required value={form.name} onChange={change}/></label><label>SKU<input name="sku" required value={form.sku} onChange={change} placeholder="STORE-001"/></label><label>Category<select name="category" required value={form.category} onChange={change}><option value="">Select a category</option>{categories.map(c=><option value={c._id} key={c._id}>{c.name}</option>)}</select></label><label>Price (PHP)<input name="price" required min="0" step="0.01" type="number" value={form.price} onChange={change}/></label><label>Stock<input name="stock" required min="0" step="1" type="number" value={form.stock} onChange={change}/></label><label>Image URL<input name="image" type="url" value={form.image} onChange={change} placeholder="https://..."/></label><label className="full">Description<textarea name="description" required rows="4" value={form.description} onChange={change}/></label><label className="check"><input name="featured" type="checkbox" checked={form.featured} onChange={change}/> Feature this product on the customer homepage</label><button className="btn" disabled={busy||!categories.length}>{busy?'Saving…':'Save product'}</button>{!categories.length&&<p className="form-note">An administrator must create a category before products can be added.</p>}</form>}{products.length?<div className="seller-product-grid">{products.map(p=><article key={p._id}><img src={img(p)}/><div><small>{p.sku}</small><h3>{p.name}</h3><p>{money(p.price)} · {p.stock} in stock</p><span className="status">{p.status}</span>{p.featured&&<span className="badge-inline">Featured</span>}</div><button className="danger" onClick={()=>remove(p._id)}><Trash2 size={16}/> Delete</button></article>)}</div>:<Empty title="No products yet" text="Use Add Product to publish the first item from your store."/>}</div>}
function CategoryManager(){
  const[items,setItems]=useState([]),[name,setName]=useState(''),[description,setDescription]=useState(''),[editing,setEditing]=useState(null),[busy,setBusy]=useState(false);
  useEffect(()=>{api.get('/categories').then(r=>setItems(r.data.data))},[]);
  const reset=()=>{setName('');setDescription('');setEditing(null)};
  const beginEdit=category=>{setName(category.name);setDescription(category.description||'');setEditing(category._id)};
  const save=async e=>{e.preventDefault();setBusy(true);try{const r=editing?await api.put(`/categories/${editing}`,{name,description}):await api.post('/categories',{name,description});setItems(current=>editing?current.map(item=>item._id===editing?r.data.data:item):[...current,r.data.data]);toast.success(editing?'Category updated':'Category created');reset()}catch(e){toast.error(e.message)}finally{setBusy(false)}};
  const remove=async id=>{if(!confirm('Delete this category?'))return;try{await api.delete(`/categories/${id}`);setItems(current=>current.filter(x=>x._id!==id));if(editing===id)reset();toast.success('Category deleted')}catch(e){toast.error(e.message)}};
  return <div><div className="manager-head"><div><h2>Product categories</h2><p>Create and edit categories sellers can use when adding products.</p></div></div><form className="category-form" onSubmit={save}><input required placeholder="Category name" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="Short description" value={description} onChange={e=>setDescription(e.target.value)}/><div className="category-form-actions"><button className="btn" disabled={busy}>{busy?'Saving…':editing?'Save changes':'Add category'}</button>{editing&&<button type="button" className="category-cancel" onClick={reset} disabled={busy}>Cancel</button>}</div></form>{items.length?<div className="table-wrap"><table><tbody>{items.map(c=><tr key={c._id}><td><b>{c.name}</b></td><td>{c.description||'—'}</td><td><div className="row-actions"><button onClick={()=>beginEdit(c)}>Edit</button><button className="danger" onClick={()=>remove(c._id)}>Delete</button></div></td></tr>)}</tbody></table></div>:<Empty title="No categories yet" text="Create the first category to let sellers add products."/>}</div>
}
const productPhotoToDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read the selected photo'));reader.onload=()=>{const photo=new Image();photo.onerror=()=>reject(new Error('Please choose a valid JPG, PNG, or WebP photo'));photo.onload=()=>{const render=(maxSize,quality)=>{const scale=Math.min(1,maxSize/Math.max(photo.width,photo.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(photo.width*scale));canvas.height=Math.max(1,Math.round(photo.height*scale));canvas.getContext('2d').drawImage(photo,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',quality)};let data=render(1200,.82);if(data.length>850000)data=render(800,.72);if(data.length>950000)return reject(new Error('The photo is too large. Please choose a smaller image.'));resolve(data)};photo.src=reader.result};reader.readAsDataURL(file)});
const blankProduct={name:'',description:'',price:'',stock:'',sku:'',category:'',image:'',sizes:'',featured:false,status:'active'};
function SellerCatalog({initial}){const[items,setItems]=useState(initial),[categories,setCategories]=useState([]),[form,setForm]=useState(blankProduct),[editing,setEditing]=useState(null),[open,setOpen]=useState(false),[busy,setBusy]=useState(false);useEffect(()=>setItems(initial),[initial]);useEffect(()=>{api.get('/categories').then(r=>setCategories(r.data.data))},[]);const change=e=>setForm({...form,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value});const choosePhoto=async e=>{const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast.error('Choose a JPG, PNG, or WebP photo');e.target.value='';return}if(file.size>5*1024*1024){toast.error('Photo must be 5 MB or smaller');e.target.value='';return}try{const image=await productPhotoToDataUrl(file);setForm(current=>({...current,image}))}catch(error){toast.error(error.message);e.target.value=''}};const begin=p=>{setEditing(p._id);setForm({name:p.name,description:p.description,price:p.price,stock:p.stock,sku:p.sku,category:p.category?._id||p.category,image:p.images?.[0]||'',sizes:(p.sizes||[]).join(', '),featured:p.featured,status:p.status});setOpen(true)};const close=()=>{setOpen(false);setEditing(null);setForm(blankProduct)};const save=async e=>{e.preventDefault();setBusy(true);try{const payload={...form,price:Number(form.price),stock:Number(form.stock),images:form.image?[form.image]:[],sizes:form.sizes.split(',').map(size=>size.trim().toUpperCase()).filter(Boolean)};delete payload.image;const r=editing?await api.put(`/products/${editing}`,payload):await api.post('/products',payload);setItems(editing?items.map(x=>x._id===editing?r.data.data:x):[r.data.data,...items]);toast.success(editing?'Product updated':'Product published');close()}catch(e){toast.error(e.message)}finally{setBusy(false)}};const remove=async id=>{if(!confirm('Permanently delete this product?'))return;try{await api.delete(`/products/${id}`);setItems(items.filter(x=>x._id!==id));toast.success('Product deleted')}catch(e){toast.error(e.message)}};return <div><div className="manager-head"><div><h2>Product management</h2><p>Create, edit, publish, archive, and manage your store products.</p></div><button className="btn" onClick={()=>open?close():setOpen(true)}>{open?<X/>:<Plus/>}{open?'Close':'Add product'}</button></div>{open&&<form className="product-form" onSubmit={save}><label>Product name<input name="name" required value={form.name} onChange={change}/></label><label>SKU<input name="sku" required value={form.sku} onChange={change}/></label><label>Category<select name="category" required value={form.category} onChange={change}><option value="">Select category</option>{categories.map(c=><option key={c._id} value={c._id}>{c.name}</option>)}</select></label><label>Price (PHP)<input name="price" type="number" min="0" step="0.01" required value={form.price} onChange={change}/></label><label>Stock<input name="stock" type="number" min="0" step="1" required value={form.stock} onChange={change}/></label><label>Status<select name="status" value={form.status} onChange={change}><option value="active">Active</option><option value="draft">Draft</option><option value="archived">Archived</option></select></label><label className="full">Available sizes<input name="sizes" value={form.sizes} onChange={change} placeholder="Example: 38, 39, 40 or S, M, L, XL"/><small className="field-hint">Separate each available size with a comma. Leave blank for products without sizes.</small></label><div className="product-photo-field full"><label>Product photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={choosePhoto}/><small>Choose a JPG, PNG, or WebP image up to 5 MB.</small></label>{form.image&&<div className="product-photo-preview"><img src={form.image} alt="Product preview"/><button type="button" onClick={()=>setForm({...form,image:''})}>Remove photo</button></div>}</div><label className="full">Image URL (optional)<input name="image" type="url" value={form.image.startsWith('data:')?'':form.image} onChange={change} placeholder="Or paste an image URL"/></label><label className="full">Description<textarea name="description" rows="4" required value={form.description} onChange={change}/></label><label className="check"><input name="featured" type="checkbox" checked={form.featured} onChange={change}/> Show as featured on the customer homepage</label><button className="btn" disabled={busy||!categories.length}>{busy?'Saving…':editing?'Update product':'Publish product'}</button>{!categories.length&&<p className="form-note">Ask the administrator to create a product category first.</p>}</form>}{items.length?<div className="seller-product-grid">{items.map(p=><article key={p._id}><img src={img(p)}/><div><small>{p.sku}</small><h3>{p.name}</h3><p>{money(p.price)} · {p.stock} in stock</p><span className="status">{p.status}</span>{p.featured&&<span className="badge-inline">Featured</span>}</div><div className="row-actions"><button onClick={()=>begin(p)}>Edit</button><button className="danger" onClick={()=>remove(p._id)}>Delete</button></div></article>)}</div>:<Empty title="No products yet" text="Add your first product to begin selling."/>}</div>}
function SellerStoreManager(){const[store,setStore]=useState(null),[form,setForm]=useState({storeName:'',description:'',logo:'',banner:''}),[busy,setBusy]=useState(false);useEffect(()=>{api.get('/sellers/store').then(r=>{setStore(r.data.data);if(r.data.data)setForm({storeName:r.data.data.storeName||'',description:r.data.data.description||'',logo:r.data.data.logo||'',banner:r.data.data.banner||''})})},[]);const save=async e=>{e.preventDefault();setBusy(true);try{const r=await api.put('/sellers/store',form);setStore(r.data.data);toast.success('Store profile updated')}catch(e){toast.error(e.message)}finally{setBusy(false)}};if(!store)return <Empty title="Store profile unavailable" text="Your seller application must be approved first."/>;return <div><div className="approval-banner"><b>Store status</b><span className="status">{store.approvalStatus}</span></div><form className="store-form" onSubmit={save}><label>Store name<input required value={form.storeName} onChange={e=>setForm({...form,storeName:e.target.value})}/></label><label>Description<textarea rows="5" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Logo URL<input type="url" value={form.logo} onChange={e=>setForm({...form,logo:e.target.value})}/></label><label>Banner URL<input type="url" value={form.banner} onChange={e=>setForm({...form,banner:e.target.value})}/></label><button className="btn" disabled={busy}>{busy?'Saving…':'Save store profile'}</button></form></div>}
function SellerOrderManager({initial}){const validOrders=value=>Array.isArray(value)?value.filter(order=>order&&Array.isArray(order.items)):[],[orders,setOrders]=useState(()=>validOrders(initial));useEffect(()=>setOrders(validOrders(initial)),[initial]);const update=async(id,status)=>{try{const response=await api.patch(`/seller/orders/${id}/status`,{status});setOrders(current=>current.map(order=>order._id===id?{...order,status:response.data.data.status,fulfillments:Array.isArray(response.data.data.fulfillments)?response.data.data.fulfillments:order.fulfillments||[]}:order));toast.success('Fulfillment status updated')}catch(e){toast.error(e.message)}};return orders.length?<div className="seller-orders">{orders.map(order=><article key={order._id}><div><b>{order.orderNumber}</b><small>{order.createdAt?new Date(order.createdAt).toLocaleDateString():'Date unavailable'}</small></div><div>{order.items.map((item,index)=><p key={item.product||index}>{item.productName||'Product'} × {item.quantity||0} — {money(item.subtotal)}</p>)}</div><select value={(Array.isArray(order.fulfillments)&&order.fulfillments[0]?.status)||'processing'} onChange={e=>update(order._id,e.target.value)}><option value="processing">Processing</option><option value="packed">Packed</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option></select></article>)}</div>:<Empty title="No seller orders yet" text="Orders containing your products will appear here."/>}
function SellerInventory(){const[items,setItems]=useState([]);useEffect(()=>{api.get('/seller/products').then(r=>setItems(r.data.data))},[]);const setStock=async(p,stock)=>{try{const r=await api.put(`/products/${p._id}`,{stock:Number(stock)});setItems(items.map(x=>x._id===p._id?r.data.data:x));toast.success('Stock updated')}catch(e){toast.error(e.message)}};return items.length?<div className="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Stock</th><th>Availability</th></tr></thead><tbody>{items.map(p=><tr key={p._id}><td><b>{p.name}</b></td><td>{p.sku}</td><td><input className="stock-input" type="number" min="0" defaultValue={p.stock} onBlur={e=>setStock(p,e.target.value)}/></td><td><span className="status">{p.stock===0?'Out of stock':p.stock<=5?'Low stock':'In stock'}</span></td></tr>)}</tbody></table></div>:<Empty title="No inventory yet" text="Add a product to start managing stock."/>}
function CustomerActions({customer,onChanged}){const[open,setOpen]=useState(false),[details,setDetails]=useState(false),[busy,setBusy]=useState(false);const deactivate=async()=>{setOpen(false);if(!confirm(`Deactivate ${customer.name}'s account? They will no longer be able to sign in.`))return;setBusy(true);try{const r=await api.patch(`/admin/users/${customer._id}/status`,{status:'suspended'});onChanged(r.data.data);toast.success('Customer account deactivated')}catch(e){toast.error(e.message)}finally{setBusy(false)}};return <><div className="action-menu"><button type="button" className="action-menu-trigger" aria-label={`Actions for ${customer.name}`} aria-expanded={open} onClick={()=>setOpen(!open)}><MoreVertical size={19}/></button>{open&&<div className="action-menu-dropdown"><button type="button" onClick={()=>{setOpen(false);setDetails(true)}}><Eye size={16}/> View details</button><button type="button" className="deactivate-action" disabled={busy||customer.accountStatus==='suspended'} onClick={deactivate}><Ban size={16}/> {customer.accountStatus==='suspended'?'Deactivated':'Deactivate'}</button></div>}</div>{details&&<div className="details-modal-backdrop" role="presentation" onMouseDown={()=>setDetails(false)}><section className="details-modal" role="dialog" aria-modal="true" aria-labelledby={`customer-${customer._id}`} onMouseDown={e=>e.stopPropagation()}><button type="button" className="details-modal-close" aria-label="Close details" onClick={()=>setDetails(false)}><X size={20}/></button><span className="eyebrow">Customer account</span><h2 id={`customer-${customer._id}`}>{customer.name}</h2><dl><div><dt>Email address</dt><dd>{customer.email}</dd></div><div><dt>Phone number</dt><dd>{customer.phone||'Not provided'}</dd></div><div><dt>Account status</dt><dd><span className="status">{customer.accountStatus||'active'}</span></dd></div><div><dt>Joined</dt><dd>{customer.createdAt?new Date(customer.createdAt).toLocaleDateString():'Unavailable'}</dd></div><div><dt>Address</dt><dd>{[customer.address?.line1,customer.address?.city,customer.address?.province,customer.address?.postalCode].filter(Boolean).join(', ')||'Not provided'}</dd></div></dl></section></div>}</>}
function StoreActions({store,onChanged}){const[open,setOpen]=useState(false),[details,setDetails]=useState(false),[busy,setBusy]=useState(false);const deactivate=async()=>{setOpen(false);if(!confirm(`Deactivate ${store.storeName}? Its products will no longer appear in the marketplace.`))return;setBusy(true);try{const r=await api.patch(`/admin/seller-applications/${store._id}`,{status:'suspended'});onChanged(r.data.data);toast.success('Store deactivated')}catch(e){toast.error(e.message)}finally{setBusy(false)}};return <><div className="action-menu"><button type="button" className="action-menu-trigger" aria-label={`Actions for ${store.storeName}`} aria-expanded={open} onClick={()=>setOpen(!open)}><MoreVertical size={19}/></button>{open&&<div className="action-menu-dropdown"><button type="button" onClick={()=>{setOpen(false);setDetails(true)}}><Eye size={16}/> View details</button><button type="button" className="deactivate-action" disabled={busy||store.approvalStatus==='suspended'} onClick={deactivate}><Ban size={16}/> {store.approvalStatus==='suspended'?'Deactivated':'Deactivate'}</button></div>}</div>{details&&<div className="details-modal-backdrop" role="presentation" onMouseDown={()=>setDetails(false)}><section className="details-modal" role="dialog" aria-modal="true" aria-labelledby={`store-${store._id}`} onMouseDown={e=>e.stopPropagation()}><button type="button" className="details-modal-close" aria-label="Close details" onClick={()=>setDetails(false)}><X size={20}/></button><span className="eyebrow">Seller store</span><h2 id={`store-${store._id}`}>{store.storeName}</h2><dl><div><dt>Owner</dt><dd>{store.seller?.name||'Unavailable'}</dd></div><div><dt>Email address</dt><dd>{store.seller?.email||'Unavailable'}</dd></div><div><dt>Store status</dt><dd><span className="status">{store.approvalStatus}</span></dd></div><div><dt>Created</dt><dd>{store.createdAt?new Date(store.createdAt).toLocaleDateString():'Unavailable'}</dd></div><div><dt>Description</dt><dd>{store.description||'No description provided'}</dd></div></dl></section></div>}</>}
function SellerReviews({items}){
  if(!items.length)return <Empty title="No product reviews yet" text="Customer comments and ratings will appear here after delivered orders are reviewed."/>;
  return <div className="seller-reviews"><div className="seller-reviews-summary"><div><span className="eyebrow">CUSTOMER FEEDBACK</span><h2>Product reviews</h2><p>See what customers say about products from your store.</p></div><strong>{items.length} {items.length===1?'review':'reviews'}</strong></div><div className="seller-review-list">{items.map(review=><article key={review._id}><div className="seller-review-product"><img src={review.product?.images?.[0]||'https://placehold.co/120x120/eaf7fd/278cc2?text=CLARAYO'} alt=""/><div><small>{review.product?.sku||'PRODUCT'}</small><h3>{review.product?.name||'Unavailable product'}</h3></div></div><div className="seller-review-rating" aria-label={`${review.rating} out of 5 stars`}><span>{'★'.repeat(review.rating)}{'☆'.repeat(5-review.rating)}</span><b>{review.rating}.0</b></div><blockquote>“{review.comment}”</blockquote><div className="reviewer-details"><div className="reviewer-avatar">{review.customer?.name?.charAt(0)?.toUpperCase()||'C'}</div><div className="reviewer-identity"><b>{review.customer?.name||'Customer'}</b><span>Verified buyer</span><small>{review.customer?.email||'Email unavailable'}</small></div><div className="review-date"><small>Reviewed on</small><time>{new Date(review.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</time></div></div></article>)}</div></div>;
}
function ReportTable({role,items}){
  const[selected,setSelected]=useState(null),isAdmin=role==='admin';
  const monthLabel=value=>{const[year,month]=String(value).split('-').map(Number);return year&&month?new Date(year,month-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'}):value};
  const sellerIncome=report=>(report.sellers||[]).reduce((sum,seller)=>sum+(Number(seller.income)||0),0);
  return <><div className="table-wrap"><table><thead><tr><th>Month</th><th>{isAdmin?'Orders':'Units sold'}</th><th>{isAdmin?'Revenue':'Sales'}</th>{isAdmin&&<th>Seller income</th>}<th>Action</th></tr></thead><tbody>{items.map((report,index)=><tr key={report._id||index}><td><b>{monthLabel(report._id)}</b><small>{report._id}</small></td><td>{isAdmin?report.orders:report.units}</td><td><span className="status">{money(isAdmin?report.revenue:report.sales)}</span></td>{isAdmin&&<td><b>{money(sellerIncome(report))}</b><small>Products sold</small></td>}<td><button type="button" className="report-view-button" onClick={()=>setSelected(report)}><Eye size={16}/> View</button></td></tr>)}</tbody></table></div>{selected&&<div className="details-modal-backdrop" role="presentation" onMouseDown={()=>setSelected(null)}><section className={`details-modal ${isAdmin?'report-details-modal':''}`} role="dialog" aria-modal="true" aria-labelledby="report-details-title" onMouseDown={e=>e.stopPropagation()}><button type="button" className="details-modal-close" aria-label="Close report" onClick={()=>setSelected(null)}><X size={20}/></button><span className="eyebrow">Monthly report</span><h2 id="report-details-title">{monthLabel(selected._id)}</h2><dl><div><dt>Report period</dt><dd>{selected._id}</dd></div><div><dt>{isAdmin?'Marketplace revenue':'Total sales'}</dt><dd>{money(isAdmin?selected.revenue:selected.sales)}</dd></div><div><dt>{isAdmin?'Orders delivered':'Units sold'}</dt><dd>{isAdmin?selected.orders:selected.units}</dd></div>{isAdmin&&<div><dt>Total seller income</dt><dd>{money(sellerIncome(selected))}</dd></div>}</dl>{isAdmin&&<div className="seller-income-section"><div><h3>Income by seller</h3><p>Product sales from delivered orders. Shipping fees are not included.</p></div>{selected.sellers?.length?<div className="seller-income-table"><table><thead><tr><th>Seller / Store</th><th>Orders</th><th>Units</th><th>Income</th></tr></thead><tbody>{selected.sellers.map((seller,index)=><tr key={String(seller.sellerId||index)}><td><b>{seller.storeName}</b><small>{seller.sellerName}</small></td><td>{seller.orders}</td><td>{seller.units}</td><td><strong>{money(seller.income)}</strong></td></tr>)}</tbody></table></div>:<p className="seller-income-empty">No seller income was recorded for this month.</p>}</div>}</section></div>}</>;
}
function FollowerActions({follower,onRemoved}){const[busy,setBusy]=useState(false);const remove=async()=>{if(!confirm(`Remove ${follower.name} from your store followers?`))return;setBusy(true);try{await api.delete(`/seller/followers/${follower._id}`);onRemoved(follower._id);toast.success('Follower removed')}catch(e){toast.error(e.message)}finally{setBusy(false)}};return <button type="button" className="danger follower-remove-button" disabled={busy} onClick={remove}><X size={16}/> {busy?'Removingâ€¦':'Remove follower'}</button>}function DataView({role,view,data,approve}){const[items,setItems]=useState(data);useEffect(()=>setItems(data),[data]);if(role==='seller'&&view==='products')return <SellerCatalog initial={data}/>;if(role==='seller'&&(view==='store'||view==='settings'))return <SellerStoreManager/>;if(role==='seller'&&view==='orders')return <SellerOrderManager initial={data}/>;if(role==='seller'&&view==='inventory')return <SellerInventory/>;if(role==='seller'&&view==='reviews')return <SellerReviews items={items}/>;if(role==='admin'&&view==='categories')return <CategoryManager/>;if(view==='reports'&&items.length)return <ReportTable role={role} items={items}/>;if(!items.length)return <Empty title={`No ${view} yet`} text="Records will appear here when they are available."/>;const updateItem=updated=>setItems(current=>current.map(item=>item._id===updated._id?updated:item));return <div className="table-wrap"><table><thead><tr><th>Record</th><th>Details</th><th>Status / Value</th><th>Action</th></tr></thead><tbody>{items.map((x,i)=><tr key={x._id||i}><td><b>{x.storeName||x.name||x.orderNumber||x._id}</b><small>{x.seller?.name||x.customer?.name||x._id}</small></td><td>{x.email||x.description||x.sku||new Date(x.createdAt||Date.now()).toLocaleDateString()}</td><td><span className="status">{view==='customers'?(x.accountStatus||'active'):(x.approvalStatus||x.status||x.role||money(x.total||x.price))}</span></td><td>{view==='applications'?<div className="actions"><button onClick={()=>approve(x._id,'approved')}>Approve</button><button className="danger" onClick={()=>approve(x._id,'rejected')}>Reject</button></div>:role==='admin'&&view==='customers'?<CustomerActions customer={x} onChanged={updateItem}/>:role==='admin'&&view==='sellers'?<StoreActions store={x} onChanged={updateItem}/>:role==='admin'&&view==='products'?<Link className="admin-view-product" to={`/products/${x._id}`} aria-label={`View ${x.name||'product'}`}><Eye size={16}/> View product</Link>:role==='seller'&&view==='followers'?<FollowerActions follower={x} onRemoved={id=>setItems(current=>current.filter(item=>item._id!==id))}/>:<ArrowRight/>}</td></tr>)}</tbody></table></div>}
function About(){return <Layout><section className="about"><span className="eyebrow">OUR STORY</span><h1>A marketplace with more heart.</h1><p>CLARAYO brings independent sellers and curious shoppers together through a calm, trustworthy, and beautifully simple shopping experience.</p><div className="about-grid"><div><b>01</b><h3>Curated quality</h3><p>Products chosen for usefulness, craft, and character.</p></div><div><b>02</b><h3>Independent sellers</h3><p>Real businesses building something meaningful.</p></div><div><b>03</b><h3>Shopping with confidence</h3><p>Secure accounts, transparent orders, and clear support.</p></div></div></section></Layout>}
function Services(){return <Layout><section className="page-title"><span className="eyebrow">CLARAYO SERVICES</span><h1>Built for every marketplace role</h1><p>One connected platform for buying, selling, fulfillment, and administration.</p></section><section className="services-page"><article><ShoppingBag/><div><span className="eyebrow">FOR CUSTOMERS</span><h2>Simple, secure shopping</h2><p>Browse real products, manage a multi-seller cart, place Cash on Delivery orders, and track progress.</p><Link className="btn" to="/products">Start shopping</Link></div></article><article><StoreIcon/><div><span className="eyebrow">FOR SELLERS</span><h2>Your store, organized</h2><p>Apply for approval, publish products, control stock, process orders, and review sales performance.</p><Link className="btn" to="/register">Create an account</Link></div></article></section></Layout>}
export default function App(){return <Routes><Route path="/" element={<RootPage/>}/><Route path="/about" element={<About/>}/><Route path="/services" element={<Services/>}/><Route path="/products" element={<Products/>}/><Route path="/categories/:slug" element={<Products/>}/><Route path="/products/:id" element={<Detail/>}/><Route path="/stores/:slug" element={<Storefront/>}/><Route path="/login" element={<Auth mode="login"/>}/><Route path="/register" element={<Auth mode="register"/>}/><Route path="/cart" element={<Cart/>}/><Route path="/checkout" element={<Guard roles={['customer','seller']}><Checkout/></Guard>}/><Route path="/order-success/:id" element={<Guard><OrderSuccess/></Guard>}/><Route path="/profile" element={<Guard><Profile/></Guard>}/><Route path="/settings" element={<Guard><CustomerSettings/></Guard>}/><Route path="/wishlist" element={<Guard roles={['customer']}><Wishlist/></Guard>}/><Route path="/my-orders" element={<Guard roles={['customer','seller']}><Orders/></Guard>}/><Route path="/my-orders/:id" element={<Guard roles={['customer','seller']}><OrderDetail/></Guard>}/><Route path="/admin/profile" element={<Guard roles={['admin']}><Dashboard role="admin" view="profile"/></Guard>}/><Route path="/admin/settings" element={<Guard roles={['admin']}><Dashboard role="admin" view="settings"/></Guard>}/><Route path="/seller/profile" element={<Guard roles={['seller']}><Dashboard role="seller" view="profile"/></Guard>}/><Route path="/seller/settings" element={<Guard roles={['seller']}><Dashboard role="seller" view="settings"/></Guard>}/>{dashNav.seller.map(([p])=><Route key={p} path={p} element={<Guard roles={['seller']}><Dashboard role="seller" view={p==='/seller'?'overview':p.split('/').pop()}/></Guard>}/>)}{dashNav.admin.map(([p])=><Route key={p} path={p} element={<Guard roles={['admin']}><Dashboard role="admin" view={p==='/admin'?'overview':p.split('/').pop()==='seller-applications'?'applications':p.split('/').pop()}/></Guard>}/>)}<Route path="*" element={<Layout><Empty title="Page not found" text="That page seems to have wandered off." action="Return to shop"/></Layout>}/></Routes>}
